with flattened as (select id, customer_id, created_at, pos + 1 as line_no, li_item.product_id, li_item.qty, li_item.price from carts lateral view outer posexplode(items) li as pos, li_item) select date_trunc('hour', created_at) as hour_window, case when price >= 234 then 'PREMIUM' else 'STANDARD' end as price_tier, case when line_no >= 3 then 'PREMIUM' else 'STANDARD' end as line_no_tier, count(*) as num_rows, approx_percentile(product_id, array(0.25, 0.5, 0.75)) as product_id_quartiles, sum(qty) as total_qty from flattened group by grouping sets ((date_trunc('hour', created_at), case when price >= 234 then 'PREMIUM' else 'STANDARD' end, case when line_no >= 3 then 'PREMIUM' else 'STANDARD' end), (date_trunc('hour', created_at), case when price >= 234 then 'PREMIUM' else 'STANDARD' end), ())
